use rwcore::*;
fn words(w:&[u16])->Vec<u8>{w.iter().flat_map(|v|v.to_be_bytes()).collect()}
fn wrap(kind:u16,offset:usize,b:&[u8])->Vec<u8>{let mut v=words(&[1,kind]);v.extend((offset as u32).to_be_bytes());v.resize(offset,0);v.extend(b);v}
fn single()->Vec<u8>{words(&[1,10,5,(-20i16) as u16,30,1,2,3,7])}
#[test]fn large_offset_and_direct_equality(){let b=single();let w=wrap(1,70000,&b);let e=parse_extension_positioning(&w,w.len()).unwrap();assert_eq!(e.offset(),70000);assert_eq!(e.target(),b.as_slice());assert_eq!(parse_gpos_extension_target(e,10,5,Default::default()).unwrap(),parse_direct_gpos_target(1,&b,10,5,Default::default()).unwrap());}
#[test]fn all_wrapper_kinds(){for k in 1..=8{let w=wrap(k,8,&[0,1]);assert_eq!(parse_extension_positioning(&w,10).unwrap().kind(),k);}for k in [0,9,10,65535]{assert!(parse_extension_positioning(&wrap(k,8,&[0,1]),10).is_err());}}
#[test]fn malformed_header_and_offsets(){let w=wrap(1,8,&single());for n in 0..10{assert!(parse_extension_positioning(&w[..n],100).is_err());}for offset in [0u32,7,1000,u32::MAX]{let mut b=w.clone();b[4..8].copy_from_slice(&offset.to_be_bytes());assert!(parse_extension_positioning(&b,100).is_err());}let mut b=w;b[1]=2;assert!(parse_extension_positioning(&b,100).is_err());}
#[test]fn homogeneous_lookup_and_aliases(){let b=wrap(1,8,&single());let mut l=GposLookup{kind:9,flags:0,subtables:vec![0,0],mark_filtering_set:None};let a=resolve_gpos_extension_lookup(&b,&l,b.len(),2).unwrap();assert_eq!(a[0],a[1]);assert!(resolve_gpos_extension_lookup(&b,&l,b.len(),1).is_err());l.subtables.push(b.len());assert!(resolve_gpos_extension_lookup(&b,&l,b.len(),3).is_err());let mut both=b.clone();both.extend(wrap(2,8,&[0,1]));l.subtables=vec![0,b.len()];assert!(resolve_gpos_extension_lookup(&both,&l,both.len(),2).is_err());l.subtables.clear();assert!(resolve_gpos_extension_lookup(&both,&l,both.len(),2).is_err());}
#[test]fn limits_and_child_failure(){let b=wrap(1,8,&single());assert!(parse_extension_target_positioning(&b,10,5,GposExtensionLimits{max_bytes:b.len()-1,..Default::default()}).is_err());assert!(parse_extension_target_positioning(&b,3,5,Default::default()).is_err());assert!(parse_direct_gpos_target(9,&b,10,5,Default::default()).is_err());}
#[test]fn context_and_chain_dispatch(){for (kind,w) in [(7,&[3,2,2,18,26,1,2,0,1,1,2,3,4,2,1,7,9,0][..]),(8,&[3,2,28,36,2,42,50,1,60,2,1,4,0,3,1,2,9,19,1,1,8,1,2,10,20,2,1,11,12,0,1,1,13][..])]{let b=words(w);let ext=wrap(kind,8,&b);let a=parse_extension_target_positioning(&ext,32,5,Default::default()).unwrap();assert_eq!(a.kind(),kind);assert_eq!(a,parse_direct_gpos_target(kind,&b,32,5,Default::default()).unwrap());assert!(parse_extension_target_positioning(&ext,32,1,Default::default()).is_err());}}
